-- 462_intake_xjz_mount_transport_rebirth_csharp_evidence.sql
-- Purpose: ingest C# restored mount, transport, rebirth, and level-exp evidence as readable Traditional Chinese server research tables.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_mount_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_mount_visual_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_mount_skill_binding;
DROP TABLE IF EXISTS god2_research._xjz_stage_mount_doll_visual;
DROP TABLE IF EXISTS god2_research._xjz_stage_transport_binding;
DROP TABLE IF EXISTS god2_research._xjz_stage_transport_flow_capture_target;
DROP TABLE IF EXISTS god2_research._xjz_stage_transport_flow_playbook_route;
DROP TABLE IF EXISTS god2_research._xjz_stage_transport_service_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_rebirth_rule_capture_target;
DROP TABLE IF EXISTS god2_research._xjz_stage_rebirth_rule_playbook_route;

CREATE TABLE god2_research._xjz_stage_mount_template (mount_template_id INT PRIMARY KEY, item_id INT NULL, mount_code VARCHAR(96) NULL, name_zh_tw VARCHAR(160) NOT NULL, generation VARCHAR(64) NOT NULL, mount_type VARCHAR(64) NULL, speed_type VARCHAR(64) NULL, model_id INT NULL, can_ride INT NOT NULL DEFAULT 1, can_teleport INT NOT NULL DEFAULT 0, teleport_map VARCHAR(128) NULL, teleport_x INT NULL, teleport_y INT NULL, teleport_cost_minutes INT NULL DEFAULT 0, ride_time_consumes INT NULL, can_recolor INT NULL, can_store_guild_storage INT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_mount_visual_template (mount_visual_id INT PRIMARY KEY, character_index INT NOT NULL, rom_file VARCHAR(255) NULL, action_category INT NOT NULL, preload_flag INT NOT NULL DEFAULT 0, hero_offset_y INT NOT NULL DEFAULT 0, rebirth_shadow_offset_y INT NOT NULL DEFAULT 0, mount_part_offset_y INT NOT NULL DEFAULT 0, shadow_index INT NOT NULL DEFAULT 0, art_definition_zh_tw TEXT NOT NULL, category_zh_tw VARCHAR(160) NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_mount_skill_binding (binding_id INT PRIMARY KEY, skill_index INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, item_id INT NOT NULL, skill_slot INT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0, UNIQUE KEY uq_stage_mount_skill (skill_index, item_id, skill_slot)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_mount_doll_visual (doll_visual_id INT PRIMARY KEY, accessory_index INT NOT NULL, beast_code INT NULL, file_identifier INT NULL, speed_bonus_x10 INT NOT NULL DEFAULT 0, rom_path VARCHAR(255) NULL, palette_range VARCHAR(64) NULL, accessory_name_zh_tw VARCHAR(160) NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_transport_binding (transport_binding_id INT PRIMARY KEY, binding_kind VARCHAR(64) NOT NULL, source_ref VARCHAR(128) NOT NULL, source_item_id INT NULL, skill_index INT NULL, skill_slot INT NULL, visual_id INT NULL, visual_ref VARCHAR(128) NULL, speed_bonus_x10 INT NULL, description_zh_tw TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_transport_flow_capture_target (target_id INT PRIMARY KEY, transport_binding_id INT NOT NULL, binding_kind VARCHAR(64) NOT NULL, source_ref VARCHAR(128) NOT NULL, source_item_id INT NULL, skill_index INT NULL, skill_slot INT NULL, visual_id INT NULL, visual_ref VARCHAR(128) NULL, speed_bonus_x10 INT NULL, description_zh_tw TEXT NOT NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, wanted_fields_json LONGTEXT NOT NULL, target_binding_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, request_hint_zh_tw TEXT NOT NULL, current_client_source TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_transport_flow_playbook_route (route_binding_id INT PRIMARY KEY, target_id INT NOT NULL, transport_binding_id INT NOT NULL, step_id INT NOT NULL, action_key VARCHAR(96) NOT NULL, binding_kind VARCHAR(64) NOT NULL, source_ref VARCHAR(128) NOT NULL, source_item_id INT NULL, skill_index INT NULL, skill_slot INT NULL, visual_id INT NULL, visual_ref VARCHAR(128) NULL, speed_bonus_x10 INT NULL, description_zh_tw TEXT NOT NULL, capture_context VARCHAR(128) NOT NULL, target_binding_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, route_id INT NOT NULL, query_id INT NOT NULL, required_run_key VARCHAR(96) NOT NULL, sample_count_sql TEXT NOT NULL, last_sample_id_sql TEXT NULL, presence_sql TEXT NOT NULL, route_state VARCHAR(64) NOT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_transport_route (target_id, route_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_transport_service_template (service_id INT PRIMARY KEY, transport_binding_id INT NOT NULL UNIQUE, binding_kind VARCHAR(64) NOT NULL, source_ref VARCHAR(128) NOT NULL, source_item_id INT NULL, skill_index INT NULL, skill_slot INT NULL, visual_id INT NULL, visual_ref VARCHAR(128) NULL, speed_bonus_x10 INT NULL, description_zh_tw TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_rebirth_rule_capture_target (target_id INT PRIMARY KEY, quest_id INT NOT NULL, quest_code VARCHAR(96) NULL, name_zh_tw VARCHAR(255) NOT NULL, step_count INT NOT NULL DEFAULT 0, requirement_count INT NOT NULL DEFAULT 0, inferred_chain_group VARCHAR(96) NOT NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, wanted_fields_json LONGTEXT NOT NULL, target_rule_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, request_hint_zh_tw TEXT NOT NULL, current_client_source TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_rebirth_rule_playbook_route (route_binding_id INT PRIMARY KEY, target_id INT NOT NULL, quest_id INT NOT NULL, step_id INT NOT NULL, action_key VARCHAR(96) NOT NULL, quest_code VARCHAR(96) NULL, name_zh_tw VARCHAR(255) NOT NULL, step_count INT NOT NULL DEFAULT 0, requirement_count INT NOT NULL DEFAULT 0, inferred_chain_group VARCHAR(96) NOT NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, target_rule_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, route_id INT NOT NULL, query_id INT NOT NULL, required_run_key VARCHAR(96) NOT NULL, sample_count_sql TEXT NOT NULL, last_sample_id_sql TEXT NULL, presence_sql TEXT NOT NULL, route_state VARCHAR(64) NOT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL DEFAULT 1, UNIQUE KEY uq_stage_rebirth_route (target_id, route_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS god2_research.xjz_mount_templates_csharp;
CREATE TABLE god2_research.xjz_mount_templates_csharp AS
SELECT m.mount_template_id, m.item_id, i.item_id AS formal_item_id, m.mount_code, m.name_zh_tw, m.generation,
       CASE m.generation WHEN 'first_generation' THEN '一代坐騎' WHEN 'second_generation' THEN '二代坐騎' ELSE m.generation END AS generation_zh_tw,
       m.mount_type, CASE m.mount_type WHEN 'teleport_beast' THEN '傳送獸' WHEN 'ride_mount' THEN '騎乘坐騎' ELSE COALESCE(m.mount_type, '未分類坐騎') END AS mount_type_zh_tw,
       m.speed_type, m.model_id, m.can_ride, m.can_teleport, m.teleport_map, m.teleport_x, m.teleport_y, COALESCE(m.teleport_cost_minutes, 0) AS teleport_cost_minutes,
       m.ride_time_consumes, m.can_recolor, m.can_store_guild_storage, m.raw_source AS source_file, m.raw_line AS source_line,
       '坐騎/傳送獸模板：服務端可用來判斷道具是否能騎乘、是否能傳送、模型與坐騎分類。' AS game_function_zh_tw,
       CASE WHEN m.can_teleport = 1 THEN '需要實機確認傳送封包與目標座標' ELSE '靜態模板可先供服務端辨識坐騎功能' END AS server_apply_note_zh_tw,
       m.evidence_status, 0 AS packet_evidence_boundary
FROM god2_research._xjz_stage_mount_template m
LEFT JOIN god2_game.items i ON i.client_item_id = m.item_id;
ALTER TABLE god2_research.xjz_mount_templates_csharp ADD PRIMARY KEY (mount_template_id);

DROP TABLE IF EXISTS god2_research.xjz_mount_visuals_csharp;
CREATE TABLE god2_research.xjz_mount_visuals_csharp AS
SELECT mount_visual_id, character_index, rom_file, action_category, preload_flag, hero_offset_y, rebirth_shadow_offset_y, mount_part_offset_y, shadow_index,
       CASE WHEN category_zh_tw REGEXP '[绁炰粰诲嫏鎺㈡湜]' THEN '坐騎外觀資源' ELSE category_zh_tw END AS category_zh_tw,
       CONCAT('坐騎外觀 ROM 對照：角色索引 ', character_index, '，動作分類 ', action_category, '，檔案 ', COALESCE(rom_file, '未提供')) AS visual_note_zh_tw,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '坐騎外觀：服務端可用來對照坐騎模型、預載與角色騎乘顯示偏移。' AS game_function_zh_tw
FROM god2_research._xjz_stage_mount_visual_template;
ALTER TABLE god2_research.xjz_mount_visuals_csharp ADD PRIMARY KEY (mount_visual_id);

DROP TABLE IF EXISTS god2_research.xjz_mount_skill_bindings_csharp;
CREATE TABLE god2_research.xjz_mount_skill_bindings_csharp AS
SELECT s.binding_id, s.skill_index, s.name_zh_tw, s.item_id, i.item_id AS formal_item_id, s.skill_slot, s.raw_source AS source_file, s.raw_line AS source_line,
       s.evidence_status, s.packet_evidence_boundary,
       '坐騎技能綁定：服務端可用來判斷坐騎道具附帶哪一格技能。' AS game_function_zh_tw,
       '技能實際效果仍需由技能效果表與戰鬥封包確認；此表只做道具到技能槽位對照。' AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_mount_skill_binding s
LEFT JOIN god2_game.items i ON i.client_item_id = s.item_id;
ALTER TABLE god2_research.xjz_mount_skill_bindings_csharp ADD PRIMARY KEY (binding_id), ADD UNIQUE KEY uq_xjz_mount_skill_bindings_csharp (skill_index, item_id, skill_slot);

DROP TABLE IF EXISTS god2_research.xjz_mount_doll_visuals_csharp;
CREATE TABLE god2_research.xjz_mount_doll_visuals_csharp AS
SELECT doll_visual_id, accessory_index, beast_code, file_identifier, speed_bonus_x10, rom_path, NULLIF(palette_range, '?') AS palette_range, accessory_name_zh_tw,
       raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '坐騎飾品/獸型外觀：服務端可用來對照坐騎外觀檔、速度加成與飾品索引。' AS game_function_zh_tw
FROM god2_research._xjz_stage_mount_doll_visual;
ALTER TABLE god2_research.xjz_mount_doll_visuals_csharp ADD PRIMARY KEY (doll_visual_id);

DROP TABLE IF EXISTS god2_research.xjz_transport_bindings_csharp;
CREATE TABLE god2_research.xjz_transport_bindings_csharp AS
SELECT t.transport_binding_id, t.binding_kind, t.source_ref, t.source_item_id, i.item_id AS formal_item_id, t.skill_index, t.skill_slot, t.visual_id, t.visual_ref, t.speed_bonus_x10,
       t.description_zh_tw, t.raw_source AS source_file, t.raw_line AS source_line, t.evidence_status, t.packet_evidence_boundary,
       '交通/傳送綁定：服務端可用來把坐騎視覺、坐騎技能、來源道具串成移動或傳送流程。' AS game_function_zh_tw
FROM god2_research._xjz_stage_transport_binding t
LEFT JOIN god2_game.items i ON i.client_item_id = t.source_item_id;
ALTER TABLE god2_research.xjz_transport_bindings_csharp ADD PRIMARY KEY (transport_binding_id);

DROP TABLE IF EXISTS god2_research.xjz_transport_flow_capture_targets_csharp;
CREATE TABLE god2_research.xjz_transport_flow_capture_targets_csharp AS
SELECT target_id, transport_binding_id, binding_kind, source_ref, source_item_id, skill_index, skill_slot, visual_id, visual_ref, speed_bonus_x10,
       description_zh_tw, capture_priority, capture_context,
       'visual_id, visual_ref, source_item_id, mount_template_id, ride_state, speed_bonus_x10, source_map_id, source_x, source_y, target_map_id, target_x, target_y, raw_packet' AS wanted_fields_zh_tw,
       target_binding_table, sample_table, request_hint_zh_tw, current_client_source, raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '交通/傳送抓包目標：用來補齊騎乘、移動速度、傳送座標與封包欄位。' AS game_function_zh_tw
FROM god2_research._xjz_stage_transport_flow_capture_target;
ALTER TABLE god2_research.xjz_transport_flow_capture_targets_csharp ADD PRIMARY KEY (target_id);

DROP TABLE IF EXISTS god2_research.xjz_transport_flow_playbook_routes_csharp;
CREATE TABLE god2_research.xjz_transport_flow_playbook_routes_csharp AS
SELECT route_binding_id, target_id, transport_binding_id, step_id, action_key, binding_kind, source_ref, source_item_id, skill_index, skill_slot, visual_id, visual_ref, speed_bonus_x10,
       description_zh_tw, capture_context, target_binding_table, sample_table, route_id, query_id, required_run_key, route_state, evidence_status, packet_evidence_boundary,
       '交通/傳送抓包路線：正式抓包時用這些路線確認每個坐騎/傳送來源的封包樣本是否存在。' AS game_function_zh_tw
FROM god2_research._xjz_stage_transport_flow_playbook_route;
ALTER TABLE god2_research.xjz_transport_flow_playbook_routes_csharp ADD PRIMARY KEY (route_binding_id), ADD UNIQUE KEY uq_xjz_transport_flow_playbook_routes_csharp (target_id, route_id);

DROP TABLE IF EXISTS god2_research.xjz_transport_service_templates_csharp;
CREATE TABLE god2_research.xjz_transport_service_templates_csharp AS
SELECT service_id, transport_binding_id, binding_kind, source_ref, source_item_id, skill_index, skill_slot, visual_id, visual_ref, speed_bonus_x10,
       description_zh_tw, raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '交通服務模板：服務端可用來建立坐騎交通服務入口，不直接推定未知封包格式。' AS game_function_zh_tw
FROM god2_research._xjz_stage_transport_service_template;
ALTER TABLE god2_research.xjz_transport_service_templates_csharp ADD PRIMARY KEY (service_id), ADD UNIQUE KEY uq_xjz_transport_service_templates_csharp (transport_binding_id);

DROP TABLE IF EXISTS god2_research.xjz_rebirth_capture_targets_csharp;
CREATE TABLE god2_research.xjz_rebirth_capture_targets_csharp AS
SELECT target_id, quest_id, quest_code, name_zh_tw, step_count, requirement_count, inferred_chain_group, capture_priority, capture_context,
       'rebirth_level, required_level, required_god_count, required_god_level, required_quest_id, rebirth_map, required_item_json, before_rebirth_level, after_rebirth_level, success, result_json' AS wanted_fields_zh_tw,
       target_rule_table, sample_table, request_hint_zh_tw, current_client_source, raw_source AS source_file, raw_line AS source_line, evidence_status, packet_evidence_boundary,
       '轉生任務抓包目標：用來確認轉生階段、需求等級、神仙需求、任務條件與結果封包。' AS game_function_zh_tw,
       '目前 C# 還原包沒有可直接落地的轉生數值規則，因此只建立抓包任務，不先寫死條件。' AS server_apply_note_zh_tw
FROM god2_research._xjz_stage_rebirth_rule_capture_target;
ALTER TABLE god2_research.xjz_rebirth_capture_targets_csharp ADD PRIMARY KEY (target_id);

DROP TABLE IF EXISTS god2_research.xjz_rebirth_playbook_routes_csharp;
CREATE TABLE god2_research.xjz_rebirth_playbook_routes_csharp AS
SELECT route_binding_id, target_id, quest_id, step_id, action_key, quest_code, name_zh_tw, step_count, requirement_count, inferred_chain_group, capture_priority, capture_context,
       target_rule_table, sample_table, route_id, query_id, required_run_key, route_state, evidence_status, packet_evidence_boundary,
       '轉生抓包路線：正式抓包時用來確認轉生任務鏈是否產生樣本，以及是否能回填轉生規則。' AS game_function_zh_tw
FROM god2_research._xjz_stage_rebirth_rule_playbook_route;
ALTER TABLE god2_research.xjz_rebirth_playbook_routes_csharp ADD PRIMARY KEY (route_binding_id), ADD UNIQUE KEY uq_xjz_rebirth_playbook_routes_csharp (target_id, route_id);

DROP TABLE IF EXISTS god2_research.xjz_level_exp_gap_csharp;
CREATE TABLE god2_research.xjz_level_exp_gap_csharp (
  gap_key VARCHAR(96) NOT NULL PRIMARY KEY,
  game_function_zh_tw VARCHAR(160) NOT NULL,
  evidence_status_zh_tw VARCHAR(160) NOT NULL,
  server_apply_note_zh_tw VARCHAR(512) NOT NULL,
  next_capture_action_zh_tw VARCHAR(512) NOT NULL,
  source_pack_id VARCHAR(96) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP VIEW IF EXISTS god2_research.vw_xjz_mount_transport_csharp_summary_zh_tw;
CREATE VIEW god2_research.vw_xjz_mount_transport_csharp_summary_zh_tw AS
SELECT '坐騎模板' AS evidence_area_zh_tw, COUNT(*) AS row_count, SUM(can_ride = 1) AS ride_enabled_count, SUM(can_teleport = 1) AS teleport_enabled_count, SUM(formal_item_id IS NOT NULL) AS linked_formal_item_count, 0 AS needs_packet_count, '坐騎/傳送獸道具功能辨識' AS game_function_zh_tw FROM god2_research.xjz_mount_templates_csharp
UNION ALL SELECT '坐騎外觀', COUNT(*), NULL, NULL, NULL, 0, '坐騎模型與騎乘顯示' FROM god2_research.xjz_mount_visuals_csharp
UNION ALL SELECT '坐騎技能綁定', COUNT(*), NULL, NULL, SUM(formal_item_id IS NOT NULL), 0, '坐騎附帶技能槽位' FROM god2_research.xjz_mount_skill_bindings_csharp
UNION ALL SELECT '坐騎飾品外觀', COUNT(*), NULL, NULL, NULL, 0, '坐騎飾品/獸型外觀與速度' FROM god2_research.xjz_mount_doll_visuals_csharp
UNION ALL SELECT '交通綁定', COUNT(*), NULL, NULL, SUM(formal_item_id IS NOT NULL), SUM(packet_evidence_boundary = 1), '坐騎交通來源對照' FROM god2_research.xjz_transport_bindings_csharp
UNION ALL SELECT '交通抓包目標', COUNT(*), NULL, NULL, NULL, SUM(packet_evidence_boundary = 1), '騎乘/移動/傳送封包欄位確認' FROM god2_research.xjz_transport_flow_capture_targets_csharp
UNION ALL SELECT '交通Playbook路線', COUNT(*), NULL, NULL, NULL, SUM(packet_evidence_boundary = 1), '正式抓包路線' FROM god2_research.xjz_transport_flow_playbook_routes_csharp
UNION ALL SELECT '交通服務模板', COUNT(*), NULL, NULL, NULL, SUM(packet_evidence_boundary = 1), '交通服務入口候選' FROM god2_research.xjz_transport_service_templates_csharp;

DROP VIEW IF EXISTS god2_research.vw_xjz_rebirth_level_csharp_summary_zh_tw;
CREATE VIEW god2_research.vw_xjz_rebirth_level_csharp_summary_zh_tw AS
SELECT '轉生抓包目標' AS evidence_area_zh_tw, COUNT(*) AS row_count, SUM(capture_priority = 'high') AS high_priority_count, SUM(packet_evidence_boundary = 1) AS needs_packet_count, '轉生條件與結果確認' AS game_function_zh_tw FROM god2_research.xjz_rebirth_capture_targets_csharp
UNION ALL SELECT '轉生Playbook路線', COUNT(*), SUM(capture_priority = 'high'), SUM(packet_evidence_boundary = 1), '正式抓包路線' FROM god2_research.xjz_rebirth_playbook_routes_csharp
UNION ALL SELECT '等級經驗缺口', COUNT(*), NULL, 1, '等級經驗需求缺證，不硬補假資料' FROM god2_research.xjz_level_exp_gap_csharp;

DROP VIEW IF EXISTS god2_research.vw_xjz_mount_transport_rebirth_text_quality_zh_tw;
CREATE VIEW god2_research.vw_xjz_mount_transport_rebirth_text_quality_zh_tw AS
SELECT '坐騎模板' AS table_zh_tw, SUM(name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') AS suspicious_text_count FROM god2_research.xjz_mount_templates_csharp
UNION ALL SELECT '坐騎外觀', SUM(category_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]' OR visual_note_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_mount_visuals_csharp
UNION ALL SELECT '坐騎技能綁定', SUM(name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_mount_skill_bindings_csharp
UNION ALL SELECT '坐騎飾品外觀', SUM(accessory_name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_mount_doll_visuals_csharp
UNION ALL SELECT '交通綁定', SUM(description_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_transport_bindings_csharp
UNION ALL SELECT '交通抓包目標', SUM(description_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]' OR request_hint_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_transport_flow_capture_targets_csharp
UNION ALL SELECT '轉生抓包目標', SUM(name_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]' OR request_hint_zh_tw REGEXP '[绁诲嫏鎺湜鍦锛]') FROM god2_research.xjz_rebirth_capture_targets_csharp;

UPDATE god2_research.xjz_csharp_apply_queue
SET safe_apply_level_zh_tw = '已匯入研究表，可供服務端功能對照',
    next_server_action_zh_tw = '坐騎模板、外觀、技能綁定、交通服務入口已整理成服務端可查表；傳送/騎乘封包欄位仍依抓包目標補樣本。',
    blocked_reason_zh_tw = NULL
WHERE queue_key = 'mount_transport_sources';

